Sample check: weight 12 kg, type I -> 5*800 + 5*700 + 2*500 + 1500 = Rs.10000.

import java.util.Scanner;

class courier
{
    String name;      // name of the customer
    double weight;    // weight of the parcel in kg
    String address;   // address of the recipient
    double bill;      // amount to be paid
    char type;        // 'D' - domestic, 'I' - international

    void accept()
    {
        Scanner sc = new Scanner(System.in);
        System.out.print("Enter name of the customer: ");
        name = sc.nextLine();
        System.out.print("Enter address of the recipient: ");
        address = sc.nextLine();
        System.out.print("Enter weight of the parcel (kg): ");
        weight = sc.nextDouble();
        System.out.print("Enter type (D - Domestic / I - International): ");
        type = sc.next().charAt(0);
    }

    void calculate()
    {
        if (weight <= 5)
            bill = weight * 800;
        else if (weight <= 10)
            bill = 5 * 800 + (weight - 5) * 700;
        else
            bill = 5 * 800 + 5 * 700 + (weight - 10) * 500;
        if (type == 'I' || type == 'i')
            bill = bill + 1500;
    }

    void print()
    {
        System.out.println("Name of customer : " + name);
        System.out.println("Address          : " + address);
        System.out.println("Weight (kg)      : " + weight);
        System.out.println("Type             : " + type);
        System.out.println("Bill amount (Rs) : " + bill);
    }

    public static void main(String args[])
    {
        courier ob = new courier();
        ob.accept();
        ob.calculate();
        ob.print();
    }
}

Sample check: perform(4, 5) prints four rows of "1 2 3 4 5"; perform(17, 5, 'Q') prints 3 and perform(17, 5, 'R') prints 2.

class Overload
{
    // curved surface area of a cone
    double perform(double r, double h)
    {
        double l = Math.sqrt(r * r + h * h);   // slant height
        double csa = Math.PI * r * l;
        return csa;
    }

    // pattern using nested for loop
    void perform(int r, int c)
    {
        for (int i = 1; i <= r; i++)
        {
            for (int j = 1; j <= c; j++)
            {
                System.out.print(j + " ");
            }
            System.out.println();
        }
    }

    // quotient or remainder
    void perform(int m, int n, char ch)
    {
        if (ch == 'Q')
            System.out.println("Quotient = " + (m / n));
        else if (ch == 'R')
            System.out.println("Remainder = " + (m % n));
        else
            System.out.println("Invalid choice");
    }

    public static void main(String args[])
    {
        Overload ob = new Overload();
        System.out.println("CSA = " + ob.perform(3.0, 4.0));
        ob.perform(4, 5);
        ob.perform(17, 5, 'Q');
        ob.perform(17, 5, 'R');
    }
}

Sample check: 121 -> reverse 121, digit sum 4 (even) -> EvenPal number.

import java.util.Scanner;

class EvenPal
{
    public static void main(String args[])
    {
        Scanner sc = new Scanner(System.in);
        System.out.print("Enter a number: ");
        int num = sc.nextInt();
        int temp = num;     // copy of the number
        int rev = 0;        // reverse of the number
        int sum = 0;        // sum of digits
        while (temp > 0)
        {
            int d = temp % 10;
            rev = rev * 10 + d;
            sum = sum + d;
            temp = temp / 10;
        }
        if (rev == num && sum % 2 == 0)
            System.out.println(num + " is an EvenPal number");
        else
            System.out.println(num + " is not an EvenPal number");
    }
}

Sample check: left = 3+5+2+1 = 11, right = 5+2+3+1 = 11 -> DIAGONAL array.

import java.util.Scanner;

class Diagonal
{
    public static void main(String args[])
    {
        Scanner sc = new Scanner(System.in);
        int a[][] = new int[4][4];
        System.out.println("Enter 16 integers:");
        for (int i = 0; i < 4; i++)
            for (int j = 0; j < 4; j++)
                a[i][j] = sc.nextInt();
        int left = 0, right = 0;   // diagonal sums
        for (int i = 0; i < 4; i++)
        {
            left = left + a[i][i];
            right = right + a[i][3 - i];
        }
        System.out.println("Sum of the left diagonal elements = " + left);
        System.out.println("Sum of the right diagonal elements = " + right);
        if (left == right)
            System.out.println("It is a DIAGONAL array");
        else
            System.out.println("It is not a DIAGONAL array");
    }
}

Sorted output: 110001, 110006, 110019, 110023, 110029, 110033, 110055, 110061.

class pincode
{
    public static void main(String args[])
    {
        int pin[] = {110061, 110001, 110029, 110023, 110055, 110006, 110019, 110033};
        int n = pin.length;
        for (int i = 0; i < n - 1; i++)
        {
            int min = i;    // index of smallest element in unsorted part
            for (int j = i + 1; j < n; j++)
            {
                if (pin[j] < pin[min])
                    min = j;
            }
            int t = pin[i];
            pin[i] = pin[min];
            pin[min] = t;
        }
        System.out.println("Sorted pin codes:");
        for (int i = 0; i < n; i++)
            System.out.println(pin[i]);
    }
}

Sample check: icse2024@gmail.com contains @, ., gmail and com -> valid gmail id. (A stricter check such as id.endsWith("@gmail.com") is also acceptable.)

import java.util.Scanner;

class Gmail
{
    public static void main(String args[])
    {
        Scanner sc = new Scanner(System.in);
        System.out.print("Enter the gmail id: ");
        String id = sc.nextLine().trim();
        if (id.indexOf('@') != -1 && id.indexOf('.') != -1
            && id.indexOf("gmail") != -1 && id.indexOf("com") != -1)
            System.out.println(id + " is a valid gmail id");
        else
            System.out.println(id + " is not a valid gmail id");
    }
}
